use clap_complete::engine::CompletionCandidate;

fn tool_cmd() -> clap::Command {
    clap::Command::new("tool")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .disable_help_subcommand(true)
        .arg(
            clap::Arg::new("tag").long("tag").short('t').num_args(1..=3)
                .value_parser(["red", "blue", "green"]),
        )
        .arg(clap::Arg::new("limit").long("limit").num_args(1).value_parser(["1", "2"]))
        .arg(clap::Arg::new("root-pos").value_parser(["input", "output"]))
        .subcommand(
            clap::Command::new("run")
                .disable_help_flag(true)
                .disable_version_flag(true)
                .arg(clap::Arg::new("tag").long("tag").short('t').num_args(1..=3)
                    .value_parser(["red", "blue", "green"]))
                .arg(clap::Arg::new("run-pos").value_parser(["job", "log"])),
        )
}

fn complete_tool(args: &[&str]) -> Vec<CompletionCandidate> {
    let mut cmd = tool_cmd();
    let args: Vec<std::ffi::OsString> = args.iter().map(std::ffi::OsString::from).collect();
    let arg_index = args.len() - 1;
    clap_complete::engine::complete(&mut cmd, args, arg_index, None).unwrap()
}

fn sig(c: &CompletionCandidate) -> (String, Option<String>, Option<String>, Option<String>, Option<usize>, bool) {
    (
        c.get_value().to_string_lossy().into_owned(),
        c.get_help().map(|h| h.to_string()),
        c.get_id().cloned(),
        c.get_tag().map(|t| t.to_string()),
        c.get_display_order(),
        c.is_hide_set(),
    )
}

