                .num_args(1..=3)
                .value_parser(["red", "blue", "green"]),
        )
        .arg(
            clap::Arg::new("limit")
                .long("limit")
                .num_args(1)
                .value_parser(["1", "2"]),
        )
        .arg(clap::Arg::new("root-pos").value_parser(["input", "output"]))
        .subcommand(
            Command::new("run")
                .disable_help_flag(true)
                .disable_version_flag(true)
                .arg(
                    clap::Arg::new("tag")
                        .long("tag")
                        .num_args(1..=3)
